import type { ColorFamily } from './theme';

// iOS app icons people can pick in Settings. Each alternate recolors the
// primary mark (assets/brand/merosplit.icon) and ships as its own Icon Composer
// bundle in assets/brand/app-icons, generated by scripts/generate-app-icons.ts.
// Edit this list, then run `pnpm icons:generate` and make a new native build.
export type AppIcon = { id: string; label: string; ground: string; left: string; right: string };
export const appIcons = [
  { id: 'default', label: 'Default', ground: '#FFFFFF', left: '#FFB21E', right: '#F2545B' },
  // One per Appearance color: the light-mode accent fills the tile, and the
  // dark-mode accent and text color make the halves.
  { id: 'cove', label: 'Cove', ground: '#00687A', left: '#6CCFE0', right: '#EAF4F5' },
  { id: 'orchid', label: 'Orchid', ground: '#6B3FA0', left: '#C7A6F2', right: '#F3EEF7' },
  { id: 'rose', label: 'Rose', ground: '#9C2A78', left: '#F0A3D6', right: '#F8EEF3' },
  { id: 'obsidian', label: 'Obsidian', ground: '#000000', left: '#FFB21E', right: '#F2545B' },
  { id: 'coral', label: 'Coral', ground: '#F2545B', left: '#FFD166', right: '#FFF4EA' },
  { id: 'marigold', label: 'Marigold', ground: '#FFB21E', left: '#FFFFFF', right: '#B5124F' },
  { id: 'rani', label: 'Rani', ground: '#D81B72', left: '#FFC93C', right: '#FFE9F2' },
  { id: 'cobalt', label: 'Cobalt', ground: '#2340FF', left: '#FFC93C', right: '#FF8FAB' },
  { id: 'peacock', label: 'Peacock', ground: '#0B6B70', left: '#F9C74F', right: '#E8F6F3' },
  { id: 'ultraviolet', label: 'Ultraviolet', ground: '#5527E0', left: '#FFB21E', right: '#FFFFFF' },
] as const satisfies readonly AppIcon[];
export type AppIconId = typeof appIcons[number]['id'];
/** 'match' follows the Appearance color; any other value is a fixed icon. */
export type AppIconChoice = 'match' | AppIconId;

// Basic keeps the primary brand icon, and Obsidian (which borrows Basic's
// colors in the app) puts the brand halves on black.
export const themeAppIcon: Record<ColorFamily, AppIconId> = { basic: 'default', cove: 'cove', orchid: 'orchid', rose: 'rose', obsidian: 'obsidian' };
export const isAppIconChoice = (value: unknown): value is AppIconChoice => value === 'match' || appIcons.some(icon => icon.id === value);
export const resolveAppIcon = (choice: AppIconChoice, family: ColorFamily): AppIconId => choice === 'match' ? themeAppIcon[family] : choice;
export const appIconLabel = (id: AppIconId): string => appIcons.find(icon => icon.id === id)!.label;

/** The alternate icon's name in the iOS bundle. null is the primary icon. */
export const nativeIconName = (id: AppIconId): string | null => id === 'default' ? null : `AppIcon${id[0].toUpperCase()}${id.slice(1)}`;
export const appIconFromNative = (name: string | null): AppIconId | null => appIcons.find(icon => nativeIconName(icon.id) === name)?.id ?? null;

// The mark from merosplit-logo.svg, drawn in its own 89 x 96 box. Previews
// scale it to fill about 72% of the tile, as Icon Composer renders the icon.
export const markPaths = { left: 'M40 0A40 40 0 0 0 40 80V61A21 21 0 0 1 40 19Z', right: 'M49 16A40 40 0 0 1 49 96V77A21 21 0 0 0 49 35Z' } as const;
export const markTransform = 'translate(50 50) scale(0.74) translate(-44.5 -48)';
